import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {inflateSync} from 'node:zlib';
import {R5,PUBLIC_REPOSITORY,PUBLIC_CAMPAIGN_URL,capturePublicOrigin,wrapPublicCapture,validatePublicCapture,
 publicProofInventory,validateExactR5Packet,validateExactR5TransportAcceptance} from './lib/campaign-v55-public-proof.mjs';

const sha=value=>createHash('sha256').update(value).digest('hex');
const digestRows=rows=>sha(JSON.stringify(rows));
const clone=value=>JSON.parse(JSON.stringify(value));
// Genuine provider controls; the root-audit/packet receipts below are explicitly
// test fixtures and never claim acceptance of those actual releases.
const PROVIDER_CONTROLS=JSON.parse(inflateSync(Buffer.from('','base64')));
const ORIGINAL_PUBLIC_LOG=inflateSync(Buffer.from('','base64'));
const ORIGINAL_ASSEMBLY_LOG=inflateSync(Buffer.from('','base64'));
const RESCUE_LOG=inflateSync(Buffer.from('','base64'));

function publicFixture(t){
 const directory=fs.mkdtempSync(path.join(os.tmpdir(),'public-capture-test-'));t.after(()=>fs.rmSync(directory,{recursive:true,force:true}));
 const sourceReview={runId:999001,runAttempt:1};
 const spec={repository:PUBLIC_REPOSITORY,publicURL:PUBLIC_CAMPAIGN_URL,sourceCommit:'a'.repeat(40),sourceTree:'b'.repeat(40),sourceParent:'c'.repeat(40),sourceReview};
 const env={GITHUB_ACTIONS:'true',GITHUB_REPOSITORY:PUBLIC_REPOSITORY,GITHUB_EVENT_NAME:'push',GITHUB_REF:'refs/heads/main',GITHUB_RUN_ATTEMPT:'1',GITHUB_SHA:'e'.repeat(40),GITHUB_RUN_ID:'999002',GITHUB_JOB:'public'};
 const run={id:999002,head_sha:env.GITHUB_SHA,head_branch:'main',event:'push',run_attempt:1,repository:{full_name:PUBLIC_REPOSITORY},html_url:'https://github.com/'+PUBLIC_REPOSITORY+'/actions/runs/999002',status:'in_progress',conclusion:null,path:'.github/workflows/publish-campaign-v55.yml'};
 const job={id:999003,run_id:run.id,run_attempt:1,head_sha:env.GITHUB_SHA,name:'Actual public capture',html_url:run.html_url+'/job/999003',status:'in_progress',conclusion:null};
 const expectedJob={key:'public',name:job.name};const origin=capturePublicOrigin({spec,run,job,expectedJob,env});
 const indexBytes=Buffer.from('explicit-candidate-fixture');
 const files=[{path:'index.html',bytes:indexBytes.length,sha256:sha(indexBytes)}];
 const stable=[...Array.from({length:40},(_,i)=>i+1),...Array.from({length:10},(_,i)=>i+42),41];
 const metadata={commit:spec.sourceCommit,gameCommit:spec.sourceCommit,interfaceCommit:spec.sourceCommit,publisherCommit:null,run:String(sourceReview.runId),verified:false,version:'v55-castle-finale',editionVersion:'fixture-v55',sourceInputsSha256:'f'.repeat(64),
  runtimeConfig:{chamberEdition:'foundation',puzzleProgression:true,campaignSequencePresentation:true,room23PhysicalPrototype:true},rooms:stable.map((stableLevel,i)=>({stableLevel,level:i+1})),files,packageFilesSha256:digestRows(files)};
 const buildInfoBytes=Buffer.from(JSON.stringify(metadata));const candidateFiles=[{path:'build-info.json',bytes:buildInfoBytes.length,sha256:sha(buildInfoBytes)},...files];
 const frame=Buffer.from('explicit-pixel-fixture');fs.writeFileSync(path.join(directory,'frame.jpg'),frame);
 const report={pass:true,errors:[],sourceCommit:spec.sourceCommit,sourceTree:spec.sourceTree,sourceReview:{runId:sourceReview.runId,runAttempt:1},localPreparation:false,publicationAccepted:false,url:PUBLIC_CAMPAIGN_URL,
  producerOrigin:{kind:'github-actions',repository:PUBLIC_REPOSITORY,headSha:origin.publisherCommit,runId:origin.publicationRun,runAttempt:1,job:origin.jobKey},
  package:{commit:metadata.commit,version:metadata.version,editionVersion:metadata.editionVersion,sourceInputsSha256:metadata.sourceInputsSha256},actualBrowserURLs:[PUBLIC_CAMPAIGN_URL],
  captures:[{file:'frame.jpg',bytes:frame.length,sha256:sha(frame),includesHTML:false}]};
 fs.writeFileSync(path.join(directory,'report.json'),JSON.stringify(report));
 const assertReport=(observed,{directory})=>{assert.equal(observed.localPreparation,false);assert.equal(observed.captures.length,1);const capture=observed.captures[0];assert.equal(capture.includesHTML,false);
  const actual=fs.readFileSync(path.join(directory,capture.file));assert.equal(actual.length,capture.bytes);assert.equal(sha(actual),capture.sha256);return {pass:true,actualURLs:observed.actualBrowserURLs,requiredFiles:['frame.jpg'],scope:'Explicit fixture semantics only'};};
 return {directory,spec,env,run,job,expectedJob,origin,buildInfoBytes,candidateFiles,expectedURLs:[PUBLIC_CAMPAIGN_URL],mode:'bare',assertReport,report};
}
function rewriteReport(fixture,change){const report=JSON.parse(fs.readFileSync(path.join(fixture.directory,'report.json')));change(report);fs.writeFileSync(path.join(fixture.directory,'report.json'),JSON.stringify(report));}

test('PUBLIC envelope preserves SOURCE metadata and actual independent producer without relabelling acceptance',t=>{
 const fixture=publicFixture(t),before=publicProofInventory(fixture.directory);const envelope=wrapPublicCapture(fixture);assert.equal(envelope.publicationAccepted,false);assert.equal(envelope.source.sourceCommit,fixture.spec.sourceCommit);
 assert.equal(envelope.producerOrigin.publicationRun,fixture.run.id);assert.equal(envelope.producerOrigin.jobURL,fixture.job.html_url);assert.deepEqual(envelope.files,before);assert.deepEqual(publicProofInventory(fixture.directory),before);
 assert.deepEqual(validatePublicCapture(envelope,fixture),envelope);
});
test('SOURCE run/commit, wrong branch/event/attempt/job/jobURL and failed producer cannot be PUBLIC',t=>{
 const f=publicFixture(t);for(const [field,value]of[['GITHUB_RUN_ID',String(f.spec.sourceReview.runId)],['GITHUB_SHA',f.spec.sourceCommit],['GITHUB_REF','refs/heads/source'],['GITHUB_EVENT_NAME','workflow_dispatch'],['GITHUB_RUN_ATTEMPT','2'],['GITHUB_JOB','source']]){
  assert.throws(()=>capturePublicOrigin({...f,env:{...f.env,[field]:value}}));}
 for(const job of [{...f.job,run_attempt:2},{...f.job,html_url:f.job.html_url+'0'},{...f.job,run_id:f.spec.sourceReview.runId},{...f.job,name:'Source'}, {...f.job,status:'completed',conclusion:'failure'}])assert.throws(()=>capturePublicOrigin({...f,job}));
 assert.throws(()=>capturePublicOrigin({...f,run:{...f.run,status:'completed',conclusion:'failure'}}));
 assert.throws(()=>capturePublicOrigin({...f,run:{...f.run,path:'.github/workflows/campaign-polish-review.yml'}}));
 assert.throws(()=>capturePublicOrigin({...f,spec:{...f.spec,sourceReview:{...f.spec.sourceReview,url:'https://github.com/'+PUBLIC_REPOSITORY+'/actions/runs/999001'}}}));
});
test('SOURCE and local-preparation reports cannot be substituted for actual PUBLIC observations',t=>{
 for(const mutation of [report=>{report.producerOrigin.runId=999001;},report=>{report.producerOrigin.headSha='a'.repeat(40);},report=>{delete report.producerOrigin;},report=>{report.localPreparation=true;},report=>{report.sourceTree='0'.repeat(40);},report=>{report.sourceReview.runId=1;},report=>{report.publicationAccepted=true;}]){
  const f=publicFixture(t);rewriteReport(f,mutation);assert.throws(()=>wrapPublicCapture(f));}
});
test('exact live URL observations reject localhost, old namespace, origin substitute and changed query',t=>{
 for(const url of ['http://127.0.0.1:4173/campaign-v55/',PUBLIC_CAMPAIGN_URL.replace('campaign-v55','tower41-native-v3'),PUBLIC_CAMPAIGN_URL.replace('amazin20.github.io','example.com'),PUBLIC_CAMPAIGN_URL+'?debug=1',PUBLIC_CAMPAIGN_URL+'#room']){
  const f=publicFixture(t);rewriteReport(f,report=>{report.actualBrowserURLs=[url];});assert.throws(()=>wrapPublicCapture(f));assert.throws(()=>wrapPublicCapture({...f,expectedURLs:[url]}));}
});
test('requested public base is kept separate from independently observed queried campaign URL',t=>{
 const f=publicFixture(t),actual=PUBLIC_CAMPAIGN_URL+'?edition=foundation&level=20&debug=1';rewriteReport(f,report=>{report.actualBrowserURLs=[actual];});
 const envelope=wrapPublicCapture({...f,expectedURLs:[actual],mode:'campaign'});assert.equal(envelope.requestedBaseURL,PUBLIC_CAMPAIGN_URL);assert.deepEqual(envelope.publicURLs,[actual]);
 rewriteReport(f,report=>{report.actualBrowserURLs=[PUBLIC_CAMPAIGN_URL];});assert.throws(()=>wrapPublicCapture({...f,expectedURLs:[actual],mode:'campaign'}));
});
test('fresh PUBLIC run/job API identity defeats stale capture envelopes',t=>{
 const f=publicFixture(t),envelope=wrapPublicCapture(f);assert.throws(()=>validatePublicCapture(envelope,{...f,run:{...f.run,id:999004,html_url:f.run.html_url.replace('999002','999004')}}));
 assert.throws(()=>validatePublicCapture({...envelope,producerOrigin:{...envelope.producerOrigin,jobId:1}},f));
});
test('capture corruption/deletion/extra auxiliary member and semantic substitute frame all block',t=>{
 for(const mutation of ['changed','deleted','extra','html']){const f=publicFixture(t),envelope=wrapPublicCapture(f);
  if(mutation==='changed')fs.writeFileSync(path.join(f.directory,'frame.jpg'),'other-frame');if(mutation==='deleted')fs.unlinkSync(path.join(f.directory,'frame.jpg'));if(mutation==='extra')fs.writeFileSync(path.join(f.directory,'auxiliary.txt'),'unclaimed');
  if(mutation==='html')rewriteReport(f,report=>{report.captures[0].includesHTML=true;});assert.throws(()=>validatePublicCapture(envelope,f));}
});
test('candidate build stamp must be byte-identical SOURCE metadata rather than a PUBLIC stamp',t=>{
 const f=publicFixture(t);const metadata=JSON.parse(f.buildInfoBytes);metadata.run=String(f.run.id);const bytes=Buffer.from(JSON.stringify(metadata));
 assert.throws(()=>wrapPublicCapture({...f,buildInfoBytes:bytes}));const rows=clone(f.candidateFiles);rows[0]={path:'build-info.json',bytes:bytes.length,sha256:sha(bytes)};
 assert.throws(()=>wrapPublicCapture({...f,buildInfoBytes:bytes,candidateFiles:rows}));
});
test('symlinked roots, symlink members and byte/path limits are rejected',t=>{
 const f=publicFixture(t),link=path.join(f.directory,'linked');fs.symlinkSync(path.join(f.directory,'frame.jpg'),link);assert.throws(()=>publicProofInventory(f.directory));fs.unlinkSync(link);
 fs.symlinkSync(f.directory,path.join(f.directory,'self'));assert.throws(()=>publicProofInventory(path.join(f.directory,'self')));fs.unlinkSync(path.join(f.directory,'self'));
 assert.throws(()=>publicProofInventory(f.directory,{maximum:1}));fs.writeFileSync(path.join(f.directory,'bad\\name'),'bad');assert.throws(()=>publicProofInventory(f.directory));
});
test('wrapping detects file or metadata drift during independent semantic callback',t=>{
 const f=publicFixture(t);assert.throws(()=>wrapPublicCapture({...f,assertReport:(...args)=>{const result=f.assertReport(...args);fs.writeFileSync(path.join(f.directory,'aux'),'drift');return result;}}));
 const g=publicFixture(t);assert.throws(()=>wrapPublicCapture({...g,assertReport:(...args)=>{const result=g.assertReport(...args);g.buildInfoBytes[0]^=1;return result;}}));
});
test('self-consistent caller SOURCE and URL rewrites during callback cannot bypass the capture snapshot',t=>{
 const f=publicFixture(t);assert.throws(()=>wrapPublicCapture({...f,assertReport:(...args)=>{const result=f.assertReport(...args);f.expectedURLs[0]='http://127.0.0.1:4173/campaign-v55/';return {...result,actualURLs:f.expectedURLs};}}),/Capture inputs changed/);
 const g=publicFixture(t);assert.throws(()=>wrapPublicCapture({...g,assertReport:(...args)=>{const result=g.assertReport(...args);g.spec.sourceReview.runId=999004;
  const metadata=JSON.parse(g.buildInfoBytes);metadata.run='999004';Buffer.from(JSON.stringify(metadata)).copy(g.buildInfoBytes);g.candidateFiles[0].sha256=sha(g.buildInfoBytes);return result;}}),/Capture inputs changed/);
});

function transportFixture(){
 const config=clone(PROVIDER_CONTROLS.config),original={run:clone(config.run),jobs:clone(config.jobs),artifact:clone(config.artifact),gitCommit:clone(PROVIDER_CONTROLS.originalGit),
  logs:[{jobId:R5.publicJobId,data:Buffer.from(ORIGINAL_PUBLIC_LOG)},{jobId:R5.assemblyJobId,data:Buffer.from(ORIGINAL_ASSEMBLY_LOG)}]};
 const rescue={run:clone(PROVIDER_CONTROLS.rescueRun),jobs:clone(PROVIDER_CONTROLS.rescueJobs),artifacts:clone(PROVIDER_CONTROLS.rescueArtifacts),gitCommit:clone(PROVIDER_CONTROLS.rescueGit),logs:[{jobId:PROVIDER_CONTROLS.rescueJobs[0].id,data:Buffer.from(RESCUE_LOG)}]};
 const artifact=rescue.artifacts.find(row=>row.name.startsWith('r5-public-verification-packet-'));const historicalPublic={sourceCommit:R5.sourceCommit,publisherCommit:R5.publisher,publicationRun:R5.publicationRun,sourceReview:clone(R5.sourceReview),sourceTree:R5.sourceTree,publicationRunAttempt:1};
 // Test-only audit and packet stubs test the provenance boundary. They do not
 // execute or attest to received packet semantics/movie checks.
 const packet={pass:true,publicationAccepted:false,originalCIConclusion:'failure',originalFailureScope:'packet-transport-budget-only',historicalPublic,artifact:clone(artifact),packetInventorySha256:'1'.repeat(64),packetBytes:123,packetSha256:'2'.repeat(64),
  rescueTransport:{repository:PUBLIC_REPOSITORY,branch:R5.rescueBranch,commit:rescue.run.head_sha,runId:rescue.run.id,runAttempt:1,runURL:rescue.run.html_url,scope:'Read-only transport producer; never a new public capture or deployment'}};
 const audit={pass:true,baselinePublicAccepted:true,originalCIConclusion:'failure',failureScope:'packet-transport-budget-only',historicalPublic,
  rescueTransport:{commit:rescue.run.head_sha,tree:rescue.gitCommit.tree.sha,runId:rescue.run.id,runAttempt:1},packet:{artifactId:artifact.id,digest:artifact.digest,inventorySha256:packet.packetInventorySha256,bytes:packet.packetBytes,sha256:packet.packetSha256}};
 const rootAudit=Buffer.from(JSON.stringify(audit));config.rescue={run:clone(rescue.run),jobs:clone(rescue.jobs),artifacts:clone(rescue.artifacts),gitCommit:clone(rescue.gitCommit),logs:[{jobId:rescue.jobs[0].id,bytes:RESCUE_LOG.length,sha256:sha(RESCUE_LOG)}],rootAudit:{bytes:rootAudit.length,sha256:sha(rootAudit)}};
 return {config,original,rescue,packet,rootAudit,deployments:[{id:R5.deploymentId,state:'failure',sha:R5.publisher,logUrl:'https://github.com/'+PUBLIC_REPOSITORY+'/actions/runs/'+R5.publicationRun+'/job/'+R5.publicJobId}]};
}
test('genuine immutable original/rescue provider controls preserve original failure and separate transport',()=>{
 const f=transportFixture();assert.equal(ORIGINAL_PUBLIC_LOG.length,R5.publicLogBytes);assert.equal(sha(ORIGINAL_PUBLIC_LOG),R5.publicLogSha256);assert.equal(ORIGINAL_ASSEMBLY_LOG.length,R5.assemblyLogBytes);assert.equal(sha(ORIGINAL_ASSEMBLY_LOG),R5.assemblyLogSha256);
 const result=validateExactR5TransportAcceptance(f);assert.equal(result.baselinePhysicalAndBytesAccepted,true);assert.equal(result.originalCIConclusion,'failure');assert.notEqual(result.rescueTransport.runId,result.historicalPublic.publicationRun);
});
test('every original PUBLIC step7-16 and exact only-step17 failure remain mandatory',()=>{
 for(let number=7;number<=17;number++){const f=transportFixture(),job=f.original.jobs.find(job=>job.id===R5.publicJobId);job.steps.find(step=>step.number===number).conclusion=number===17?'success':'failure';assert.throws(()=>validateExactR5TransportAcceptance(f));}
 const f=transportFixture();f.original.run.conclusion='success';assert.throws(()=>validateExactR5TransportAcceptance(f));
});
test('original complete provider logs cannot be truncated, corrupted, swapped or replaced by markers',()=>{
 for(const change of ['truncated','corrupt','swapped','markers']){const f=transportFixture();if(change==='truncated')f.original.logs[0].data=f.original.logs[0].data.subarray(1);if(change==='corrupt')f.original.logs[1].data[0]^=1;
  if(change==='swapped')[f.original.logs[0].data,f.original.logs[1].data]=[f.original.logs[1].data,f.original.logs[0].data];if(change==='markers')f.original.logs[0].data=Buffer.from('ValueError: Verification packet exceeds bounded transport budget');assert.throws(()=>validateExactR5TransportAcceptance(f));}
});
test('SOURCE stamp, old PUBLIC producer, wrong rescue attempt/job/origin and incomplete uploads reject',()=>{
 for(const change of ['source','old','attempt','job','origin','upload']){const f=transportFixture();if(change==='source')f.rescue.run.id=R5.sourceReview.runId;if(change==='old')f.rescue.run.head_sha=R5.publisher;
  if(change==='attempt')f.rescue.run.run_attempt=2;if(change==='job')f.rescue.jobs[0].html_url+='0';if(change==='origin')f.rescue.artifacts[0].workflow_run.id=R5.publicationRun;if(change==='upload')f.rescue.jobs[0].steps.find(step=>step.number===7).conclusion='skipped';assert.throws(()=>validateExactR5TransportAcceptance(f));}
});
test('joint config/provider mutation cannot substitute original workflow or remove rescue restore/decode roles',()=>{
 for(const [field,value]of[['head_branch','source'],['path',R5.rescueWorkflow],['event','workflow_dispatch']]){const f=transportFixture();f.original.run[field]=value;f.config.run[field]=value;assert.throws(()=>validateExactR5TransportAcceptance(f));}
 for(const number of [2,3,4,5,6]){const f=transportFixture();f.rescue.jobs[0].steps=f.rescue.jobs[0].steps.filter(step=>step.number!==number);f.config.rescue.jobs=clone(f.rescue.jobs);assert.throws(()=>validateExactR5TransportAcceptance(f));}
 const f=transportFixture();f.rescue.jobs[0].name='Generic successful job';f.config.rescue.jobs=clone(f.rescue.jobs);assert.throws(()=>validateExactR5TransportAcceptance(f));
});
test('unknown newer deployment never falls back to older original bd release',()=>{
 for(const state of ['success','failure','error','inactive','pending']){const f=transportFixture();f.deployments.push({id:R5.deploymentId+1,state,sha:'0'.repeat(40),logUrl:f.deployments[0].logUrl});assert.throws(()=>validateExactR5TransportAcceptance(f));}
 const f=transportFixture();f.deployments[0].logUrl+='0';assert.throws(()=>validateExactR5TransportAcceptance(f));
});
test('actual independent root audit pin and all packet/source/transport tuple fields are mandatory',()=>{
 for(const field of ['baselinePublicAccepted','originalCIConclusion','source','transport','packet']){const f=transportFixture(),audit=JSON.parse(f.rootAudit);if(field==='baselinePublicAccepted')audit.baselinePublicAccepted=false;if(field==='originalCIConclusion')audit.originalCIConclusion='success';
  if(field==='source')audit.historicalPublic.sourceCommit='0'.repeat(40);if(field==='transport')audit.rescueTransport.runId=R5.publicationRun;if(field==='packet')audit.packet.artifactId=R5.fullArtifactId;
  f.rootAudit=Buffer.from(JSON.stringify(audit));f.config.rescue.rootAudit={bytes:f.rootAudit.length,sha256:sha(f.rootAudit)};assert.throws(()=>validateExactR5TransportAcceptance(f));}
 const f=transportFixture();f.rootAudit[0]^=1;assert.throws(()=>validateExactR5TransportAcceptance(f));delete f.config.rescue;assert.throws(()=>validateExactR5TransportAcceptance(f));
});

async function packetFixture(t){
 const directory=fs.mkdtempSync(path.join(os.tmpdir(),'r5-members-test-'));t.after(()=>fs.rmSync(directory,{recursive:true,force:true}));const zip=path.join(directory,'outside.zip');fs.writeFileSync(zip,'explicit-zip-fixture');const members=path.join(directory,'members');fs.mkdirSync(members);fs.writeFileSync(path.join(members,'auxiliary.txt'),'fixture');
 const files=publicProofInventory(members),packet={schemaVersion:1,kind:'foundation20-and-tower41-native-public-verification-packet',pass:true,sourceCommit:R5.sourceCommit,publisherCommit:R5.publisher,publicationRun:R5.publicationRun,sourceReview:clone(R5.sourceReview),maximumBytes:100000000,files,bytes:files[0].bytes,filesSha256:digestRows(files),
  fullPrivateProofRequiredForFinalAcceptance:true,independentPublicUnionReconstructionRequiredForCheckpointAcceptance:true,fullPrivateArchiveBytesDownloaded:false,fullPrivateNestedArchiveAudited:false,privateArchiveAccepted:false,imagesIncluded:false,productionIncluded:false,sourceCodeIncluded:false,nestedArchivesIncluded:false};
 fs.writeFileSync(path.join(members,'verification-packet.json'),JSON.stringify(packet));const initial=publicProofInventory(members),artifact=clone(PROVIDER_CONTROLS.rescueArtifacts.find(row=>row.name.startsWith('r5-public-verification-packet-')));artifact.size_in_bytes=fs.statSync(zip).size;artifact.digest='sha256:'+sha(fs.readFileSync(zip));
 const verifyExtracted=async()=>({pass:true,zipBytes:artifact.size_in_bytes,zipSha256:artifact.digest.slice(7),files:publicProofInventory(members),bytes:publicProofInventory(members).reduce((n,row)=>n+row.bytes,0),inventorySha256:digestRows(publicProofInventory(members))});
 return {directory:members,zip,artifact,config:clone(PROVIDER_CONTROLS.config),verifyExtracted,initial};
}
test('received packet deleted/extra/changed member fails before semantic or movie callbacks',async t=>{
 for(const change of ['changed','deleted','extra']){const f=await packetFixture(t);if(change==='changed')fs.writeFileSync(path.join(f.directory,'auxiliary.txt'),'changed');if(change==='deleted')fs.unlinkSync(path.join(f.directory,'auxiliary.txt'));if(change==='extra')fs.writeFileSync(path.join(f.directory,'extra.txt'),'unclaimed');
  await assert.rejects(()=>validateExactR5Packet({...f,assertSemantics:()=>assert.fail('Semantic callback must not run'),decodeMovie:()=>assert.fail('Movie callback must not run')}),/Deleted\/extra\/changed packet member/);}
});
test('packet needs exact ZIP hash and complete independent member/CRC verification',async t=>{
 const f=await packetFixture(t);await assert.rejects(()=>validateExactR5Packet({...f,verifyExtracted:undefined}),/member\/CRC/);await assert.rejects(()=>validateExactR5Packet({...f,verifyExtracted:async()=>({pass:true,files:[]})}));
 fs.writeFileSync(f.zip,'changed ZIP');await assert.rejects(()=>validateExactR5Packet(f));
});
test('received packet producer cannot be original PUBLIC or SOURCE despite valid-looking member metadata',async t=>{
 const f=await packetFixture(t);for(const id of [R5.publicationRun,R5.sourceReview.runId])await assert.rejects(()=>validateExactR5Packet({...f,artifact:{...f.artifact,workflow_run:{...f.artifact.workflow_run,id}}}));
});
